def wrap(text, width):
    lines = []
    cur = ""
    for w in re.split(r'\s+', text):
        # Check if we need to wrap BEFORE adding the word
        # We need at least width - 1 characters in the current line
        if len(cur) + len(w) > width - 1:
            lines.append(cur)
            cur = w
        elif cur:
            # Add a space between words that fit on the same line
            cur += " " + w
        else:
            # First word, just add it with space padding
            cur += " " + w
    if cur:
        lines.append(cur)
